const rawText = $json.content?.parts
  ?.find(part => typeof part.text === 'string')
  ?.text;

if (!rawText) {
  throw new Error('Gemini no devolvió contenido de texto para analizar.');
}

let cleanedText = rawText.trim();

// Protección por si el modelo alguna vez agrega bloques Markdown.
cleanedText = cleanedText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '');

let analysis;

try {
  analysis = JSON.parse(cleanedText);
} catch (error) {
  throw new Error(
    `La respuesta de Gemini no contiene un JSON válido: ${error.message}`
  );
}

return [
  {
    json: {
      airtable_record_id: $('Crear caso técnico').first().json.id,
      id_caso:
        $('Crear caso técnico').first().json.fields?.['ID Caso'] ?? '',
      ...analysis,
    },
  },
];

const rawText = $json.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error('Gemini no devolvió una respuesta para el cliente.');
}

const cleanedText = rawText
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '');

let parsed;

try {
  parsed = JSON.parse(cleanedText);
} catch (error) {
  throw new Error(
    `La respuesta sugerida no contiene un JSON válido: ${error.message}`
  );
}

if (!parsed.mensaje) {
  throw new Error('El JSON generado no contiene el campo "mensaje".');
}

// Tomamos el ID desde un nodo que siempre se ejecuta,
// independientemente de que el IF salga por true o false.
const casoActualizado = $('Actualizar caso con análisis IA').first().json;
const idCaso = casoActualizado?.fields?.['ID Caso'];

if (!idCaso) {
  throw new Error('No se pudo recuperar el ID Caso desde Airtable.');
}

return [
  {
    json: {
      id_caso: idCaso,
      respuesta_sugerida: parsed.mensaje,
    },
  },
];
